#!/usr/bin/env bash
unset ANTHROPIC_API_KEY
exec claude -p "$1"

import re

BANNED_CONSTRUCTOR = re.compile(r'Anthropic\(\s*api_key')


def check(text: str) -> bool:
    """True when the paid constructor appears — used to FAIL a build."""
    return bool(BANNED_CONSTRUCTOR.search(text))

def explain(route: str) -> str:
    if route in ('bedrock', 'vertex'):
        return 'That route reaches a paid Anthropic endpoint and is refused.'
    return 'ok'
